{
  "name": "opencode-openjev",
  "version": "0.2.0",
  "description": "Typed decisions for the Opencode harness via Jev (System One) or OpenJev equivalent — Choice/Noul/Score with calibrated probabilities, no text generation",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "jev",
    "typesafe",
    "system-one",
    "openjev",
    "typed-decisions",
    "structured-output"
  ],
  "license": "MIT",
  "author": "OpenJev Contributors",
  "repository": {
    "type": "git",
    "url": "https://github.com/darwintechlab/openjev.git"
  },
  "homepage": "https://github.com/darwintechlab/openjev#readme",
  "bugs": {
    "url": "https://github.com/darwintechlab/openjev/issues"
  },
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist",
    "skill",
    "README.md",
    "SETUP.md",
    "LICENSE"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit",
    "test": "node --test test/**/*.test.mjs",
    "test:mock": "JEV_BACKEND=mock node --test test/**/*.test.mjs",
    "bench:eval": "node bench/eval.mjs",
    "prepublishOnly": "npm run typecheck && npm run build && npm test",
    "lint": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.29",
    "@opencode/plugin": ">=2.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    }
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.32"
  },
  "devDependencies": {
    "typescript": "^5.6.0",
    "@types/node": "^22.0.0",
    "@opencode/plugin": "^2.0.16"
  },
  "engines": {
    "node": ">=20"
  },
  "publishConfig": {
    "access": "public"
  }
}
